-- stray – englische Texte (Teil 32), Schlüssel = deutscher Originaltext
local _, ns = ...
local E = ns.LocaleEN

-- stray-Tasche (Kern, Fenster)
E["Blendet alle eingeschalteten stray-Anzeigen ein und macht sie frei verschiebbar – ohne Shift. Klick wählt eine Anzeige aus: Daneben öffnet sich ein kleines Fenster mit X/Y (ab Bildschirmmitte), Größe in Prozent und – wo vorhanden – Breite und Höhe; Pfeiltasten schieben sie um 1 px, mit Shift um 10 px. Shift + Rechtsklick setzt eine Anzeige ganz auf Standard zurück. „Zurück“ oder Strg + Z macht den letzten Schritt rückgängig. Esc hebt die Auswahl auf, ein weiteres Esc oder „Fertig“ beendet den Modus. Die Leiste oben schaltet Raster und Einrasten an anderen Anzeigen und der Bildschirmmitte.\n\nBetrifft alle eingeschalteten stray-Anzeigen: Bedrohungsliste, DMG-Meter, Haltbarkeit, EP-Tracker, Taschenfenster, Flugzeit, Würfelfenster, Gefahr-Hinweis und die Warntexte. Geht nur außerhalb des Kampfes. Auch per /stray edit."] = "Shows all enabled stray displays and makes them freely movable – no Shift needed. Click selects a display: a small window opens next to it with X/Y (from the screen center), size in percent and – where available – width and height; arrow keys move it by 1 px, with Shift by 10 px. Shift + right-click fully resets a display to default. “Back” or Ctrl + Z undoes the last step. Esc clears the selection, another Esc or “Done” ends the mode. The bar at the top toggles the grid and snapping to other displays and the screen center.\n\nAffects all enabled stray displays: threat list, damage meter, durability, XP tracker, bag window, flight time, roll window, danger notice and the warning texts. Only out of combat. Also via /stray edit."
E["Erst „stray-Tasche“ einschalten (weiter oben)."] = "Turn on \"stray bag\" first (further up)."
E["stray-Tasche"] = "stray bag"
E["Ersetzt Blizzards Taschen durch ein eigenes Fenster: alle Taschen mit Suche, Abschnitten und Platz-Anzeige. B-Taste, Rucksack-Knopf und Händler öffnen dann dieses Fenster. Der Schlüsselring bleibt bei Blizzard.\n\nKopfzeile ziehen verschiebt das Fenster, der Griff unten rechts ändert die Größe (Breite in Spalten). Im Kampf kann das Fenster nicht aufgehen – dann zeigt WoW seine eigenen Taschen.\n\nAusschalten wirkt sofort; ganz sauber wird es nach Neuladen (/reload)."] = "Replaces Blizzard's bags with its own window: all bags with search, sections and slot counter. The B key, the backpack button and vendors then open this window. The keyring stays with Blizzard.\n\nDragging the header moves the window, the grip at the bottom right resizes it (width in columns). The window cannot open during combat – WoW then shows its own bags.\n\nTurning it off works immediately; it is fully clean after a reload (/reload)."
E["Ansicht"] = "View"
E["Pro Tasche"] = "Per bag"
E["Eine Tasche"] = "One bag"
E["Kategorien"] = "Categories"
E["„Pro Tasche“: je Tasche ein Abschnitt. „Eine Tasche“: alle normalen Taschen in einem Raster. „Kategorien“: nach Art der Gegenstände gruppiert."] = "\"Per bag\": one section per bag. \"One bag\": all normal bags in one grid. \"Categories\": grouped by item type."
E["Spalten"] = "Columns"
E["Wie viele Plätze nebeneinander stehen. Ziehst du das Fenster unten rechts breiter oder schmaler, ändert sich dieser Wert mit."] = "How many slots sit side by side. If you drag the window wider or narrower at the bottom right, this value changes with it."
E["Feldgröße"] = "Slot size"
E["Größe der einzelnen Gegenstandsfelder in Pixeln. Standard: 36."] = "Size of the individual item slots in pixels. Default: 36."
E["Fenster sperren"] = "Lock window"
E["Das Taschenfenster lässt sich dann nicht verschieben und seine Größe nicht ändern. Das Schloss unten im Fenster schaltet dasselbe."] = "The bag window then cannot be moved or resized. The lock at the bottom of the window toggles the same thing."
E["Gleiche Gegenstände zusammenfassen"] = "Merge identical items"
E["Fasst in der Ansicht „Kategorien“ gleiche Gegenstände auf einem Feld zusammen und zeigt die Gesamtzahl."] = "In the \"Categories\" view, merges identical items into one slot and shows the total count."
E["Inventar"] = "Inventory"
E["Fenster ist gesperrt"] = "Window is locked"
E["Gesperrt: das Fenster lässt sich nicht verschieben und seine Größe nicht ändern."] = "Locked: the window cannot be moved or resized."
